package com.mamtrex.hospital.laboratory;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/lab-orders") public class LabOrderController { private final LabOrderRepository repo; private final AuditService audit; public LabOrderController(LabOrderRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String testCode, @jakarta.validation.constraints.NotBlank String specimen, @jakarta.validation.constraints.NotBlank String result, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public LabOrder create(@Valid @RequestBody Request r){var e=repo.save(new LabOrder(r.patientId(), r.testCode(), r.specimen(), r.result(), r.status()));audit.record("CREATE","LabOrder",e.getId().toString(),"created");return e;} @GetMapping public List<LabOrder> list(){return repo.findAll();} @GetMapping("/{id}") public LabOrder get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("LabOrder not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("LabOrder not found: "+id);repo.deleteById(id);audit.record("DELETE","LabOrder",id.toString(),"deleted");} }
